@startuml
class Customer {
  +name : string
  +accountNumber : string
}

class Broker {
  +name : string
}

class InsurancePolicy {
  +type : string
  +price : float
  +billingCycle : string
}

class Offer {
  +date : date
  +method : string
}

class Contract {
  +date : date
}

class Invoice {
  +amount : float
  +frequency : string
}

class ClaimCase {
  +status : string
}

class Estimator {
  +name : string
  +expertise : string
}

class EstimatorReport {
  +content : string
  +date : date
}

class CompensationDecision {
  +eligibleCosts : float
  +isApproved : boolean
}

class Claim {
  +date : date
}

Broker "0..1" -- "*" Customer : manages
Customer "1" -- "*" InsurancePolicy : signs
Customer "1" -- "*" Offer : receives
Customer "1" -- "*" Claim : submits
InsurancePolicy "1" -- "1" Contract : is part of
Customer "1" -- "1" Contract : signs
Contract "1" -- "1" Invoice : generates
Claim "1" -- "1..*" ClaimCase : results in
ClaimCase "1" -- "*" EstimatorReport : is assessed by
Estimator "1" -- "*" EstimatorReport : issues
ClaimCase "1" -- "0..1" CompensationDecision : results in
CompensationDecision "1" -- "1" ClaimCase : applies to
@enduml

